import fs from "node:fs";
import path from "node:path";
import type { AppDatabase } from "./database.js";

interface MigrationFile {
  version: number;
  name: string;
  filePath: string;
}

function discoverMigrations(directory: string): MigrationFile[] {
  if (!fs.existsSync(directory)) return [];

  return fs
    .readdirSync(directory, { withFileTypes: true })
    .filter((entry) => entry.isFile() && /^\d{3}_.+\.sql$/.test(entry.name))
    .map((entry) => {
      const version = Number.parseInt(entry.name.slice(0, 3), 10);
      return { version, name: entry.name, filePath: path.join(directory, entry.name) };
    })
    .sort((left, right) => left.version - right.version);
}

export function runMigrations(
  database: AppDatabase,
  directory = path.resolve(process.cwd(), "migrations"),
): number[] {
  database.exec(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      version INTEGER PRIMARY KEY,
      name TEXT NOT NULL,
      applied_at TEXT NOT NULL
    )
  `);

  const applied = new Set(
    database
      .prepare("SELECT version FROM schema_migrations ORDER BY version")
      .all()
      .map((row) => (row as { version: number }).version),
  );

  const completed: number[] = [];
  for (const migration of discoverMigrations(directory)) {
    if (applied.has(migration.version)) continue;
    const sql = fs.readFileSync(migration.filePath, "utf8");
    const apply = database.transaction(() => {
      database.exec(sql);
      database
        .prepare(
          "INSERT INTO schema_migrations(version, name, applied_at) VALUES (?, ?, ?)",
        )
        .run(migration.version, migration.name, new Date().toISOString());
    });
    apply.immediate();
    completed.push(migration.version);
  }

  database.pragma("optimize");
  return completed;
}

--- config ---
import path from "node:path";

export interface AppConfig {
  host: string;
  port: number;
  databasePath: string;
  nodeEnv: "development" | "test" | "production";
  clientDirectory: string;
  metadata: {
    deadlineMs: number;
    connectTimeoutMs: number;
    maxHtmlBytes: number;
    maxIconBytes: number;
    maxRedirects: number;
    concurrency: number;
  };
}

function positiveInteger(value: string | undefined, fallback: number, name: string): number {
  if (value === undefined || value === "") return fallback;
  const parsed = Number.parseInt(value, 10);
  if (!Number.isSafeInteger(parsed) || parsed <= 0) {
    throw new Error(`${name} must be a positive integer`);
  }
  return parsed;
}

export function loadConfig(
  env: NodeJS.ProcessEnv = process.env,
  cwd = process.cwd(),
): AppConfig {
  const nodeEnv = env.NODE_ENV ?? "development";
  if (nodeEnv !== "development" && nodeEnv !== "test" && nodeEnv !== "production") {
    throw new Error("NODE_ENV must be development, test, or production");
  }

  const configuredDatabase = env.DATABASE_PATH ?? "data/bookmarks.sqlite";

  return {
    host: env.HOST || "0.0.0.0",
    port: positiveInteger(env.PORT, 4000, "PORT"),
    databasePath:
      configuredDatabase === ":memory:"
        ? configuredDatabase
        : path.resolve(cwd, configuredDatabase),
    nodeEnv,
    clientDirectory: path.resolve(cwd, env.CLIENT_DIRECTORY ?? "dist/client"),
    metadata: {
      deadlineMs: positiveInteger(env.METADATA_DEADLINE_MS, 5_000, "METADATA_DEADLINE_MS"),
      connectTimeoutMs: positiveInteger(
        env.METADATA_CONNECT_TIMEOUT_MS,
        2_000,
        "METADATA_CONNECT_TIMEOUT_MS",
      ),
      maxHtmlBytes: positiveInteger(
        env.METADATA_MAX_HTML_BYTES,
        1_048_576,
        "METADATA_MAX_HTML_BYTES",
      ),
      maxIconBytes: positiveInteger(
        env.METADATA_MAX_ICON_BYTES,
        262_144,
        "METADATA_MAX_ICON_BYTES",
      ),
      maxRedirects: positiveInteger(
        env.METADATA_MAX_REDIRECTS,
        5,
        "METADATA_MAX_REDIRECTS",
      ),
      concurrency: positiveInteger(
        env.METADATA_CONCURRENCY,
        3,
        "METADATA_CONCURRENCY",
      ),
    },
  };
}

